mapper.select:
select id, tenant_id, point_code, point_name, area_id, equipment_id, source_system, source_tag, metric_type, unit, high_high, high, low, low_low, status, created_at, updated_at, deleted from monitor_point where tenant_id = #{tenantId} and deleted = 0
and (point_code like concat('%', #{keyword}, '%') or point_name like concat('%', #{keyword}, '%'))
and status = #{status}
order by id desc limit #{limit} offset #{offset}

select count(1) from monitor_point where tenant_id = #{tenantId} and deleted = 0
and (point_code like concat('%', #{keyword}, '%') or point_name like concat('%', #{keyword}, '%'))
and status = #{status}
